INSERT /* setWelcomePage */
  INTO CT_WLCMPG (
       WLCM_NUMB, VERS_NUMB, SUBX_TITL, MAIN_TITL, PAGE_DESC, IMGE_URLX, SORT_ORDR, DPLY_YSNO
     , REGI_ADMN, REGI_DATE, UPDT_ADMN, UPDT_DATE
) VALUES (
       #{wlcmNumb,jdbcType=BIGINT}, #{versNumb}, #{subxTitl}, #{mainTitl}, #{pageDesc}
     , #{imgeUrlx,jdbcType=VARCHAR}, #{sortOrdr}, #{dplyYsno}
     , #{regiAdmn}, COALESCE(#{regiDate,jdbcType=TIMESTAMP}, CURRENT_TIMESTAMP)
     , #{updtAdmn,jdbcType=BIGINT}
     , CASE WHEN #{updtAdmn,jdbcType=BIGINT} IS NULL THEN NULL ELSE CURRENT_TIMESTAMP END
)

