UPDATE /* uptWelcomePage */ CT_WLCMPG
   SET SUBX_TITL = #{subxTitl}, MAIN_TITL = #{mainTitl}, PAGE_DESC = #{pageDesc}
     , IMGE_URLX = #{imgeUrlx,jdbcType=VARCHAR}, SORT_ORDR = #{sortOrdr}
     , UPDT_ADMN = #{updtAdmn}, UPDT_DATE = CURRENT_TIMESTAMP
 WHERE WLCM_NUMB = #{wlcmNumb}
   AND VERS_NUMB = #{versNumb}
   AND DPLY_YSNO = #{dplyYsno}

UPDATE /* uptWelcomePageDeployOn */ CT_WLCMPG
   SET DPLY_YSNO = #{yes}, DPLY_ADMN = #{dplyAdmn}, DPLY_DATE = CURRENT_TIMESTAMP
 WHERE WLCM_NUMB = #{wlcmNumb} AND VERS_NUMB = #{versNumb}
